attempts.raw:
{
  "plan": "O programa Anchor declara `authority: Signer<'info>` na struct Withdraw, portanto o compilador Anchor ja insere a verificacao de assinatura. O cenario monta um vault PDA com seeds [b"vault", authority] e authority como dono, faz um deposit legitimo para popular o saldo, e entao tenta chamar withdraw removendo a flag de signer da authority (mantendo-a como writable/readonly nao-signer) para testar a hipotese de Missing Signer Check. Se o ataque for rejeitado, a hipotese esta bloqueada; se passar, o saldo do vault diminui e os lamports vao para o recipient sem assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

let (system_id, system_acc) = system_program_account();

// Baseline: initialize cria o vault PDA
let init_ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_id, false),
]);
let init_accounts = vec![
    (vault_pda, empty_account()),
    (authority, wallet(10_000_000_000)),
    (system_id, system_acc.clone()),
];
let r_init = env.baseline("initialize vault", &init_ix, &init_accounts);

// Baseline: deposit para popular o saldo
let deposit_ix = env.anchor_ix("deposit", &(1_000_000u64,), vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_id, false),
]);
let deposit_accounts = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (authority, after(&r_init, &authority).clone()),
    (system_id, system_acc.clone()),
];
let r_dep = env.baseline("deposit 1000000", &deposit_ix, &deposit_accounts);

// Ataque: withdraw sem a assinatura da authority
let attack_ix = env.anchor_ix("withdraw", &(500_000u64,), vec![
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // sem signer
    AccountMeta::new(recipient, false),
]);
let attack_accounts = vec![
    (vault_pda, after(&r_dep, &vault_pda).clone()),
    (authority, after(&r_dep, &authority).clone()),
    (recipient, wallet(1_000_000)),
];
let r = env.attack("withdraw sem assinatura da authority", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let vault_after = after(&r, &vault_pda);
    let recipient_after = after(&r, &recipient);
    let balance_after = read_u64(vault_after.data(), 40);
    env.effect("saldo do vault reduzido sem assinatura da authority", balance_after == 500_000);
    env.effect("recipient recebeu lamports sem assinatura da authority", recipient_after.lamports() == 1_500_000);
}"
}

